{
  // Check if the string `name` ends in "b0".
  size_t len = strlen(name);
  int i = len - 1;
  int digit_count = 0;
  while (i >= 0 && isdigit((unsigned char)name[i])) {
    i--;
    digit_count++;
  }
  if (digit_count > 0 && i >= 1 && name[i] == 'b' && name[i - 1] == '_') {
    const char *num_str = &name[i + 1];
    int num = atoi(num_str);
    if (num == 0) {
      return true;
    } else {
      return false;
    }

